func patchRequestBody() *openapi3.RequestBodyRef {
	patchSchema := &openapi3.SchemaRef{Value: openapi3.NewObjectSchema()}
	return &openapi3.RequestBodyRef{
		Value: &openapi3.RequestBody{
			Required: true,
			Content: openapi3.Content{
				"application/merge-patch+json": &openapi3.MediaType{Schema: patchSchema},
				"application/json-patch+json":  &openapi3.MediaType{Schema: patchSchema},
				"application/shorthand-patch":  &openapi3.MediaType{Schema: patchSchema},
				"application/json":             &openapi3.MediaType{Schema: patchSchema},
			},
		},
	}
}

// requestSchema documents unconditional required tags only when handlers enforce
// them. Custom validation and conditional tags remain application contracts.
func requestSchema(value any, schemas openapi3.Schemas) *openapi3.SchemaRef {
	// A customizer disables openapi3gen's type-only cache. Keep each field
	// independent even in relaxed modes: series-name constraints must not
	// tighten unrelated strings that happen to share the same Go type.
	ref, err := openapi3gen.NewSchemaRefForValue(value, schemas, openapi3gen.SchemaCustomizer(
		func(_ string, _ reflect.Type, _ reflect.StructTag, _ *openapi3.Schema) error { return nil },
	))
	if err != nil {
		panic("generate request schema: " + err.Error())
	}
	if "strict" == "strict" {
		ref = requestValidationSchema(ref, reflect.TypeOf(value), nil, make(map[reflect.Type]bool))
	}
	return ref
}

// requestFieldRequired considers only this value's tags, before validation can
// skip it or dive into its elements. Required on a non-pointer struct is ignored
// by the handler's validator configuration.
func requestFieldRequired(typ reflect.Type, tags []string) bool {
	if typ.Kind() == reflect.Struct {
		return false
	}
	for _, tag := range tags {
		switch tag {
		case "required":
			return true
		case "-", "omitempty", "omitnil", "dive", "structonly", "nostructlevel":
			return false
		}
	}
	return false
}

func requestValidationSkipped(typ reflect.Type, tags []string) bool {
	for _, tag := range tags {
		if tag == "dive" {
			break
		}
		if tag == "-" || tag == "structonly" || tag == "nostructlevel" {
			return true
		}
	}
	return typ.Kind() == reflect.Struct && slices.Contains(tags, "omitempty")
}

// requestEmbeddedFieldValidated keeps promoted JSON fields tied to their
// anonymous parents. VisibleFields alone loses the validation context of those
// parents. A named JSON parent is handled recursively through its own property.
func requestEmbeddedFieldValidated(typ reflect.Type, index []int) bool {
	for _, i := range index[:len(index)-1] {
		parent := typ.Field(i)
		if name := strings.Split(parent.Tag.Get("json"), ",")[0]; name != "" {
			return false
		}
		tags := strings.Split(parent.Tag.Get("validate"), ",")
		if requestValidationSkipped(parent.Type, tags) {
			return false
		}
		// An absent anonymous pointer has no JSON property on which to make
		// child requirements conditional. Do not require its promoted fields
		// unless the parent itself must be present.
		if parent.Type.Kind() == reflect.Pointer && !requestFieldRequired(parent.Type, tags) {
			return false
		}
		typ = parent.Type
		for typ.Kind() == reflect.Pointer {
			typ = typ.Elem()
		}
	}
	return true
}

// requestValidationSchema follows handler validation from the request root.
// Copy each visited schema: the same Go type can be validated through one field
// and skipped through another, so constraints must not leak via shared schemas.
func requestValidationSchema(
	ref *openapi3.SchemaRef,
	typ reflect.Type,
	tags []string,
	active map[reflect.Type]bool,
) *openapi3.SchemaRef {
	if ref == nil || ref.Value == nil {
		return ref
	}
	fieldType := typ
	for typ.Kind() == reflect.Pointer {
		typ = typ.Elem()
	}
	if active[typ] {
		return ref
	}
	schema := *ref.Value
	schema.Required = slices.Clone(schema.Required)
	if requestFieldRequired(fieldType, tags) {
		schema.Nullable = false
		if fieldType.Kind() == reflect.String {
			schema.MinLength = max(schema.MinLength, 1)
		}
	}
	result := &openapi3.SchemaRef{Value: &schema}
	// omitempty can skip a zero-valued struct even though its JSON object is
	// present. Its nested requirements cannot be expressed unconditionally.
	if requestValidationSkipped(fieldType, tags) {
		return result
	}
	active[typ] = true
	defer delete(active, typ)
	switch typ.Kind() {
	case reflect.Struct:
		schema.Properties = make(openapi3.Schemas, len(ref.Value.Properties))
		for name, property := range ref.Value.Properties {
			schema.Properties[name] = property
		}
		for _, field := range reflect.VisibleFields(typ) {
			if !requestEmbeddedFieldValidated(typ, field.Index) {
				continue
			}
			name := strings.Split(field.Tag.Get("json"), ",")[0]
			property := schema.Properties[name]
			if property == nil {
				continue
			}
			fieldTags := strings.Split(field.Tag.Get("validate"), ",")
			schema.Properties[name] = requestValidationSchema(property, field.Type, fieldTags, active)
			if requestFieldRequired(field.Type, fieldTags) && !slices.Contains(schema.Required, name) {
				schema.Required = append(schema.Required, name)
			}
		}
	case reflect.Slice, reflect.Array, reflect.Map:
		dive := slices.Index(tags, "dive")
		if dive < 0 {
			break
		}
		elementTags := tags[dive+1:]
		if typ.Kind() == reflect.Map {
			// Map key tags do not apply to the values in additionalProperties.
			if len(elementTags) > 0 && elementTags[0] == "keys" {
				end := slices.Index(elementTags, "endkeys")
				if end < 0 {
					break
				}
				elementTags = elementTags[end+1:]
			}
			schema.AdditionalProperties.Schema = requestValidationSchema(schema.AdditionalProperties.Schema, typ.Elem(), elementTags, active)
			break
		}
		schema.Items = requestValidationSchema(schema.Items, typ.Elem(), elementTags, active)
	}
	return result
}

// componentSchemaRef retains the JSON reference while resolving its value for direct validation.
func componentSchemaRef(spec *openapi3.T, name string) *openapi3.SchemaRef {
	return openapi3.NewSchemaRef("#/components/schemas/"+name, spec.Components.Schemas[name].Value)
}

// errorResponse returns the common error response schema.
func errorResponse(spec *openapi3.T) *openapi3.ResponseRef {
	return &openapi3.ResponseRef{
		Value: openapi3.NewResponse().
			WithDescription("Error response").
			WithJSONSchemaRef(componentSchemaRef(spec, "ErrorResponse")),
	}
}
